import random
from scipy import stats

def task_func(animals, mean):
    # Handle edge case where no animals are specified
    if not animals:
        return {}

    # Generate the number of customers from a Poisson distribution with the specified mean
    num_customers = stats.poisson.rvs(mean)

    # Initialize a dictionary to track sales for each animal type
    sales_summary = {animal: 0 for animal in animals}

    # If there are customers, simulate their purchases
    if num_customers > 0:
        # Generate a list of random animal choices for the customers
        purchases = random.choices(animals, k=num_customers)

        # Update the sales counts based on purchases
        for animal in purchases:
            sales_summary[animal] += 1

    return sales_summary
